const actions = {'Start cadence':'start_cadence','Restart cadence':'restart_cadence','Do not contact':'do_not_contact','Booked':'booked'};

function normalizePhone(value) {
  if (value === null || value === undefined) return null;
  let phone = String(value).trim();
  if (!phone || !/^\+?[\d\s().-]+$/.test(phone)) return null;
  const digits = phone.replace(/\D/g, '');
  if (digits.startsWith('001') && digits.length === 13) phone = digits.slice(3);
  else if (digits.startsWith('1') && digits.length === 11) phone = digits.slice(1);
  else if (digits.length === 10) phone = digits;
  else return null;
  return /^[2-9]\d{2}[2-9]\d{6}$/.test(phone) ? '+1' + phone : null;
}

function normalizeDob(value) {
  const text = String(value ?? '').trim();
  const dayFirst = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (dayFirst) {
    const day = Number(dayFirst[1]);
    const month = Number(dayFirst[2]);
    const year = Number(dayFirst[3]);
    const dt = new Date(Date.UTC(year, month - 1, day));
    if (dt.getUTCFullYear() === year && dt.getUTCMonth() === month - 1 && dt.getUTCDate() === day) {
      return year.toString().padStart(4, '0') + '-' + month.toString().padStart(2, '0') + '-' + day.toString().padStart(2, '0');
    }
    return null;
  }
  const serial = Number(value);
  if (!Number.isFinite(serial) || serial < 1 || serial > 100000) return null;
  return new Date(Date.UTC(1899, 11, 30) + Math.floor(serial) * 86400000).toISOString().slice(0, 10);
}

const output = [];
for (const [index, item] of $input.all().entries()) {
  const row = item.json;
  const command = String(row.Action || '').trim();
  if (!actions[command]) continue;

  const errors = [];
  const sheetRowNumber = Number(row.row_number ?? row.rowNumber);
  if (!Number.isInteger(sheetRowNumber) || sheetRowNumber < 2) errors.push('Sheet row number is unavailable');
  const sheetPhone = String(row['Phone Number'] ?? '').trim();

  const phone = normalizePhone(sheetPhone);
  const dob = normalizeDob(row['Date Of Birth']);
  if (!phone) errors.push('invalid phone number');

  const leadId = String(row['Lead ID'] || '').trim() || null;
  if (command !== 'Start cadence' && !leadId) errors.push('Lead ID is required');

  if (command === 'Start cadence') {
    for (const key of ['Name','Date Of Birth','Location','Title']) {
      if (!String(row[key] ?? '').trim()) errors.push(key + ' is required');
    }
    if (!dob) errors.push('Date Of Birth must be DD/MM/YYYY');
  }

  const email = String(row.Email || '').trim().toLowerCase();
  if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('invalid email');
  if (!globalThis.crypto?.randomUUID) throw new Error('Web Crypto UUID generation is unavailable');

  const requestId = globalThis.crypto.randomUUID();
  output.push({
    json: {
      ...row,
      sheetPhone,
      sheetRowNumber,
      valid: errors.length === 0,
      validationError: errors.join('; '),
      originalCommand: command,
      actionRequestId: requestId,
      actionStartedAt: new Date().toISOString(),
      existingLeadId: leadId,
      requestBody: {
        action: actions[command],
        lead_id: command === 'Start cadence' ? null : leadId,
        lead: {
          full_name: row.Name ? String(row.Name).trim() : null,
          phone,
          email: email || null,
          date_of_birth: dob,
          location: row.Location ? String(row.Location).trim() : null,
          title: row.Title ? String(row.Title).trim() : null
        }
      }
    },
    pairedItem: {item: index}
  });
}
return output;

const actionRequestId = String($json['Action Request ID'] ?? $json.actionRequestId ?? '').trim();
const matches = $('Validate and Build Intake').all().filter(
  item => String(item.json.actionRequestId ?? '').trim() === actionRequestId
);
if (!actionRequestId || matches.length !== 1) {
  throw new Error('Could not uniquely match the processing row by Action Request ID');
}
const source = matches[0].json;
const timestamp = Math.floor(Date.now()/1000).toString();
const rawBody = JSON.stringify(source.requestBody);
const secret = $env.RPT_N8N_INTAKE_SECRET;
if (!secret) throw new Error('Missing RPT_N8N_INTAKE_SECRET');
if (!globalThis.crypto?.subtle) throw new Error('Web Crypto API is unavailable in this n8n instance');
const encoder = new TextEncoder();
const key = await globalThis.crypto.subtle.importKey('raw',encoder.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);
const signed = await globalThis.crypto.subtle.sign('HMAC',key,encoder.encode(timestamp + '.' + rawBody));
const signatureHex = Array.from(new Uint8Array(signed)).map(byte=>byte.toString(16).padStart(2,'0')).join('');
return {json:{...source,rawBody,timestamp,signature:'sha256=' + signatureHex}};

const signedItems = $('Sign Intake Request').all();
const signedByRequest = new Map(
  signedItems.map(item => [String(item.json.actionRequestId ?? ''), item.json])
);
const output = [];

for (const [index, item] of $input.all().entries()) {
  const response = item.json;
  const status = Number(response.statusCode || 0);
  let body = response.body || {};
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { body = {}; }
  }

  const responseRequestId = String(body.request_id ?? '');
  const source = signedByRequest.get(responseRequestId) || signedItems[index]?.json;
  if (!source) throw new Error('Could not match the AWS response to its source Sheet row');

  const success = status === 200 || status === 201;
  const temporary = status === 0 || [408,425,429].includes(status) || status >= 500;
  const labels = {cadence_started:'Cadence started',already_started:'Already in Cadence',cadence_restarted:'Cadence restarted',do_not_contact_applied:'Do not contact applied',booked_applied:'Booked'};
  const detail = typeof body.detail === 'string' ? body.detail : (typeof body.code === 'string' ? body.code : (response.error?.message || 'request rejected'));

  let actionResult = '';
  let finalStartedAt = '';
  if (success) {
    actionResult = labels[body.result] || 'Completed';
  } else if (temporary) {
    actionResult = 'Retrying 1/3: ' + source.originalCommand;
    finalStartedAt = new Date().toISOString();
  } else {
    actionResult = 'Error: ' + String(detail).slice(0,180);
  }

  output.push({
    json: {
      ...source,
      httpStatus: status,
      leadId: body.lead_id || source.existingLeadId || '',
      actionResult,
      finalStartedAt
    },
    pairedItem: {item: index}
  });
}
return output;
